--
-- Snapshot   : commit 2cab09e / tag as-built-2026-09-03
-- Source     : local demo database (Docker container `konma-postgres`,
--              host port 5433, db/user `konma`), PostgreSQL 16.15.
-- Scope      : DATA ONLY. The schema is not in this file — it is reproduced by
--              running the five migrations in backend/prisma/migrations/ in
--              directory order:
--                npx prisma migrate deploy
--              then loading this file:
--                psql -U konma -d konma -f sample-data.sql
--
-- Produced by (verbatim):
--   docker exec konma-postgres pg_dump -U konma -d konma \
--     --data-only --inserts --no-owner > raw-dump.sql
--
-- SANITIZED by (verbatim, GNU sed):
--   sed -E \
--    -e 's/^(INSERT INTO public\."User" VALUES \((.[^'"'"']*., ){3})'"'"'[^'"'"']*'"'"'/\1'"'"'REDACTED'"'"'/' \
--    -e 's/^(INSERT INTO public\."RefreshToken" VALUES \((.[^'"'"']*., ){2})'"'"'[^'"'"']*'"'"'/\1'"'"'REDACTED'"'"'/' \
--    -e 's/^(INSERT INTO public\."PasswordResetToken" VALUES \((.[^'"'"']*., ){2})'"'"'[^'"'"']*'"'"'/\1'"'"'REDACTED'"'"'/' \
--    raw-dump.sql > sample-data.sql
--
--   Column 4 of "User" is password_hash; column 3 of "RefreshToken" and of
--   "PasswordResetToken" is token_hash. Every one now reads 'REDACTED'
--   (70 substitutions: 9 User + 61 RefreshToken; PasswordResetToken has 0 rows).
--
-- VERIFIED by (all four return 0):
--   grep -cE '\$2[aby]?\$|$ar[g]on' sample-data.sql        # bcrypt / argon2
--   grep -cE 'eyJ[A-Za-z0-9_-]{10,}' sample-data.sql      # JWT
--   grep -nE "'[0-9a-f]{32,}'" sample-data.sql | grep -vc '_prisma_migrations'
--   (the surviving 32+ hex strings are _prisma_migrations.checksum values —
--    migration integrity hashes, deliberately kept as evidence, not secrets)
--
-- NOT redacted, on purpose:
--   * _prisma_migrations.checksum  — proves which migrations were applied.
--   * razorpay_order_id / razorpay_payment_id / razorpay_refund_id — test-mode
--     gateway references, not credentials; load-bearing for the unique-index
--     evidence in 02-database.md.
--   * SystemSetting.value — inspected row by row; holds only tunables
--     (xp_rules, loyalty rates, cron times). No keys or secrets.
--   * The \restrict / \unrestrict tokens below are pg_dump 16.15 psql-injection
--     guards (a per-dump nonce), not credentials. psql < 16 will not recognise
--     them; delete those two lines if restoring with an older client.
--
-- NOT sanitized, FLAGGED: User.name and User.email are the project team's own
-- demo accounts (@konma.store), not synthetic identities. See the ⚠️ note in
-- docs/evidence-pack/02-database.md §Sample data before circulating externally.
--
-- 1,338 lines / 531 KB / 788 INSERT statements across 57 relations
-- (56 application tables + _prisma_migrations). 15 of the 71 models are empty.
-- ============================================================================

